import { Form, Input, Button, Stack } from '@design-schema/react';

const signInFields = (
  <Stack gap="normal">
    <Input label="Email" name="email" type="email" required />
    <Input label="Password" name="password" type="password" required />
  </Stack>
);

const signInActions = <Button label="Sign in" type="submit" />;

<Form name="sign-in" label="Sign in" actions={signInActions}>{signInFields}</Form>

